INSERT INTO `visionmission` VALUES ('1', 'ራእይ', '                                                                                          \r\n                           ኣብ 2037 ከተማታትና ዴሞክራሲን ሰናይ ምምሕዳር ዝተረጋገፀለን፣ ንነበርተን ምችዋት፣\r\n		ማእኸል ኢንዱስትሪን ማዕኸላይ እቶት ዘለወንን ከተማታት  ኮይነን ምርአይ፡፡                                                                                                                     ');
INSERT INTO `visionmission` VALUES ('2', 'ልእክቶ', '                                                                                                                                                                                                                                                                              \r\n                        ልኡኽና ኣብ ከተማታት ትግራይ ልምዓታዊ ሰራዊት ብምህናፅ ንደኣንት ብምጥንኻር፣ ኢንዱስትሪ፣ ንግድን ኢንቨስትመንትን ብምስፍሕፋሕ ፍትሓዊ ምሕደራ መሬት ብምርግጋፅ፣ግልጋሎት መሰረተ ልምዓት ብፅሬትን ብመጠንን ብምግፋሕ ምዕሩይን ዘላቕን ምኽታም ብምርግጋፅ ከተማታና ኣብ ዝመፅእ መዋቕራዊ (Structural transformation) ለውጢ መሪሕ ተርኣ ክትፃወት ምግባር እዩ፡፡                                                                                                                                                                                                                                                                                                                 ');
INSERT INTO `visionmission` VALUES ('3', 'ክብርታት', '\r\n                        ካብ ግዕዝይና ዝፀረየ ስርዓት ምሕደራ ሃፍቲ ክንሃንፅ ኢና!\r\nሙያዊ ስነ-ምግባር ንሕሊ\r\n  ንድሌት ህዝብን ዜጋታትን ቀዳምነት ንህብ \r\n  ንድኽነትን ክራይ ኣካብነትን ንፅየፍ፣\r\n ህዝባውነትን ውፍይነትን ንላበስ፣  እናሰራሕና ንመሃር እናተምሃርና ንሰርሕ፣\r\n ትካላዊ ዴሞክራሲያዊ ስርዓትና ነጠናኽር፣\r\n ምሕዝነት፣ መገልገላይነት፣ ተወዳዳራይነት\r\nንሓባራዊ ውፅኢት ንሰርሕ ብውፅኢትና ንሕተት\r\nብውድድር ንኣምን\r\n ጋንታዊ መንፈስ ስራሕ ነዕቢ                       ');
INSERT INTO `sellingtransferrules` VALUES ('5', 'መንበሪ', '0.75', 'G+1', '1ይ1ይ', '3200.00');
